package remediation

import (
	"strings"

	"github.com/anthnel/devdesk/internal/scan"
)

// The Pod Security Standards profile of a Kubernetes finding (DEVDESK-686,
// S-01). Trivy writes the link to the standard, with a #baseline or #restricted
// anchor, in the References of the rules that implement it; the table below is
// that anchor written down, so it is known without a scan that kept the
// references (a cached result) and can be corrected where Trivy is not enough
// (KSV-0104). TestThePodSecurityTableMatchesTrivy keeps it honest against a
// recorded Trivy output; a rule the table lacks falls back on the anchor.

// Profile is a Pod Security Standards profile.
type Profile string

const (
	ProfileBaseline   Profile = "baseline"
	ProfileRestricted Profile = "restricted"
)

// Covers reports whether target requires p: restricted covers baseline.
func (target Profile) Covers(p Profile) bool {
	return target == ProfileRestricted || target == p
}

// PSS is the Pod Security profile of a finding. FromTrivy is set when the
// anchor was read in References and the rule is not in the table.
type PSS struct {
	Profile   Profile
	FromTrivy bool
}

// pssLinkBase is the page every anchor sits on.
const pssLinkBase = "https://kubernetes.io/docs/concepts/security/pod-security-standards/#"

// ruleSeccomp is KSV-0104, the one rule whose profile depends on the manifest.
var ruleSeccomp = RuleKey("KSV-0104")

// pssProfiles maps RuleKey to the profile Trivy's checks anchor. KSV-0117
// (ports below 1024) and KSV-0119 (NET_RAW) link the standard without an
// anchor, so they name no profile and are left out on purpose.
var pssProfiles = map[string]Profile{
	RuleKey("KSV-0002"): ProfileBaseline,
	RuleKey("KSV-0008"): ProfileBaseline,
	RuleKey("KSV-0009"): ProfileBaseline,
	RuleKey("KSV-0010"): ProfileBaseline,
	RuleKey("KSV-0017"): ProfileBaseline,
	RuleKey("KSV-0022"): ProfileBaseline,
	RuleKey("KSV-0023"): ProfileBaseline,
	RuleKey("KSV-0024"): ProfileBaseline,
	RuleKey("KSV-0025"): ProfileBaseline,
	RuleKey("KSV-0026"): ProfileBaseline,
	RuleKey("KSV-0027"): ProfileBaseline,
	RuleKey("KSV-0103"): ProfileBaseline,
	RuleKey("KSV-0104"): ProfileBaseline,

	RuleKey("KSV-0001"): ProfileRestricted,
	RuleKey("KSV-0012"): ProfileRestricted,
	RuleKey("KSV-0028"): ProfileRestricted,
	RuleKey("KSV-0030"): ProfileRestricted,
	RuleKey("KSV-0105"): ProfileRestricted,
	RuleKey("KSV-0106"): ProfileRestricted,
	RuleKey("KSV-0121"): ProfileRestricted,
}

// PodSecurity returns the profile that requires the rule behind f, and false
// when the finding is not a Pod Security one: not a Trivy misconfiguration, a
// rule that names no profile, or no rule at all.
//
// KSV-0104 is the exception to the table: Trivy anchors it #baseline, but it
// fires on a missing seccomp profile too, which only the restricted profile
// requires. Its SeccompOrigin decides; an unknown origin counts as baseline,
// so nothing is hidden without proof.
func PodSecurity(f scan.Finding) (PSS, bool) {
	if f.Source != scan.SourceTrivyMisconfig {
		return PSS{}, false
	}
	key := RuleKey(f.ID)
	if p, ok := pssProfiles[key]; ok {
		if key == ruleSeccomp && f.SeccompOrigin == "absent" {
			p = ProfileRestricted
		}
		return PSS{Profile: p}, true
	}
	if p, ok := pssAnchor(f.References); ok {
		return PSS{Profile: p, FromTrivy: true}, true
	}
	return PSS{}, false
}

// pssAnchor reads the profile out of a reference list: the link to the
// standard with a known anchor.
func pssAnchor(refs []string) (Profile, bool) {
	for _, r := range refs {
		anchor, ok := strings.CutPrefix(r, pssLinkBase)
		if !ok {
			continue
		}
		if p := Profile(anchor); p == ProfileBaseline || p == ProfileRestricted {
			return p, true
		}
	}
	return "", false
}
package config

import (
	"log"
	"slices"
)

// The Pod Security profile a context aims at (DEVDESK-686, S-01).
//
// The names are stated here and in internal/remediation, which config must not
// import; TestTheProfileNamesMatchTheConfig (internal/remediation) holds the two
// in step.
const (
	// PSSProfileAll is the default: nothing is hidden by the filter.
	PSSProfileAll = "all"
	// PSSProfileBaseline aims at the baseline profile.
	PSSProfileBaseline = "baseline"
	// PSSProfileRestricted aims at the restricted profile, which includes baseline.
	PSSProfileRestricted = "restricted"
)

// PSSProfiles is the set scan.pss_profile cycles through in the configuration view.
func PSSProfiles() []string {
	return []string{PSSProfileAll, PSSProfileBaseline, PSSProfileRestricted}
}

// PSSProfileValid reports whether scan.pss_profile is absent or one of the set.
func (c ScanConfig) PSSProfileValid() bool {
	return c.PSSProfile == "" || slices.Contains(PSSProfiles(), c.PSSProfile)
}

// EffectivePSSProfile is the profile in force: the value when it is valid and
// non-empty, all otherwise.
func (c ScanConfig) EffectivePSSProfile() string {
	if c.PSSProfile == "" || !c.PSSProfileValid() {
		return PSSProfileAll
	}
	return c.PSSProfile
}

// warnInvalidPSSProfile logs a scan.pss_profile outside the set. The file is
// left alone: a typo is not silently rewritten.
func warnInvalidPSSProfile(c ScanConfig) {
	if !c.PSSProfileValid() {
		log.Printf("WARN [config] scan.pss_profile %q is not %s, %s or %s, using %s",
			c.PSSProfile, PSSProfileAll, PSSProfileBaseline, PSSProfileRestricted, PSSProfileAll)
	}
}
package scan

import (
	"log"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/anthnel/devdesk/internal/k8s"
)

// Why a KSV-0104 finding fired (DEVDESK-686, S-01). Trivy words the finding the
// same for an explicit Unconfined and for a missing seccomp profile, and
// points at the container's block rather than at the line that says
// Unconfined, so neither the message nor the span tells the two apart. The
// manifest is read again at scan time, the way the Kubernetes fixes read it
// (§3.80): the document at the reported line, the container by its name inside
// the reported lines.
const (
	SeccompUnconfined = "unconfined"
	SeccompAbsent     = "absent"
)

// seccompContainer is how KSV-0104 names its container: lower case and double
// quotes, unlike the other KSV rules ("Container 'api' of …").
var seccompContainer = regexp.MustCompile(`container "([^"]+)"`)

// isSeccompRule reports whether id is KSV-0104, in any of the three spellings
// Trivy and the cache have used. This package cannot import remediation, where
// RuleKey lives.
func isSeccompRule(id string) bool {
	id = strings.ReplaceAll(strings.TrimPrefix(strings.ToUpper(strings.TrimSpace(id)), "AVD-"), "-", "")
	return id == "KSV0104" || id == "KSV104"
}

// annotateSeccomp sets SeccompOrigin on the kubernetes KSV-0104 findings of a
// directory scan, reading each file once. It never fails the scan: whatever it
// cannot confirm leaves the origin empty, which reads as "unknown".
func annotateSeccomp(root string, findings []Finding) {
	byFile := map[string][]int{}
	for i, f := range findings {
		if f.Source == SourceTrivyMisconfig && f.IaCType == "kubernetes" && isSeccompRule(f.ID) {
			byFile[f.File] = append(byFile[f.File], i)
		}
	}
	if len(byFile) == 0 {
		return
	}
	dir, err := os.OpenRoot(root)
	if err != nil {
		log.Printf("WARN [scan] seccomp origin: cannot open %s: %v", root, err)
		return
	}
	defer func() { _ = dir.Close() }()

	for file, indexes := range byFile {
		name := filepath.FromSlash(file)
		if !filepath.IsLocal(name) {
			log.Printf("WARN [scan] seccomp origin: %s is outside the scanned directory", file)
			continue
		}
		content, err := k8s.ReadManifestIn(dir, name)
		if err != nil {
			log.Printf("WARN [scan] seccomp origin: cannot read %s: %v", file, err)
			continue
		}
		for _, i := range indexes {
			findings[i].SeccompOrigin = seccompOrigin(content, findings[i])
		}
	}
}

// seccompOrigin classifies one KSV-0104 finding from the manifest's bytes:
// SeccompUnconfined, SeccompAbsent, or "" when it cannot tell (the file
// changed since Trivy read it, the container is not at the reported lines, a
// profile is now set).
func seccompOrigin(content []byte, f Finding) string {
	m := seccompContainer.FindStringSubmatch(f.Message)
	if m == nil || f.Line <= 0 {
		return ""
	}
	doc, ok := k8s.DocumentAt(content, f.Line)
	if !ok {
		return ""
	}
	for _, spec := range k8s.PodSpecs(doc) {
		for _, c := range spec.Containers {
			if k8s.Scalar(c, "name") != m[1] {
				continue
			}
			if f.EndLine > 0 && (c.Line < f.Line || c.Line > f.EndLine) {
				continue
			}
			switch t := k8s.SeccompType(doc, spec, c); {
			case strings.EqualFold(t, "unconfined"):
				return SeccompUnconfined
			case t == "":
				return SeccompAbsent
			}
			return ""
		}
	}
	return ""
}
